        if bases.iter().any(|b| {
            repo.find_branch(&format!("origin/{}", b), BranchType::Remote).ok().and_then(|br| {
                br.get().shorthand().map(|s| s == b)
            }).unwrap_or(false)
        }) {
            println!("    {}/{} [base]", remote, branch);
        }
    }

    // Analyze what to delete
    let to_delete = analyze_deletions(&repo, &local_branches, &remote_branches, &bases, args)?;

    // Print results
    if !to_delete.merged_local.is_empty() {
        println!("\nDelete merged local branches:");
        for branch in &to_delete.merged_local {
            println!("  - {}", branch);
            if args.dry_run {
                println!("Delete branch {} (dry run).", branch);
            }
        }
    }

    Ok(())
}

struct BranchInfo {
    merged_local: Vec<String>,
}

fn get_base_branches(repo: &Repository, args: &Args) -> Result<Vec<String>> {
    if let Some(ref bases) = args.bases {
        return Ok(bases.split(',').map(|s| s.trim().to_string()).collect());
    }

    // Try to get from git symbolic-ref
    let mut bases = Vec::new();

    if let Ok(remotes) = repo.remotes() {
        for remote_name in remotes.iter().flatten() {
            // Try to get the remote HEAD
            if let Ok(ref_name) = std::process::Command::new("git")
                .args(&["symbolic-ref", &format!("refs/remotes/{}/HEAD", remote_name)])
                .output()
            {
                if ref_name.status.success() {
                    let output = String::from_utf8_lossy(&ref_name.stdout);
                    if let Some(branch) = output.strip_prefix(&format!("refs/remotes/{}/", remote_name)) {
                        bases.push(branch.trim().to_string());
                    }
                }
            }
        }
    }

    if bases.is_empty() {
        eprintln!("I can't detect base branch! Try following any resolution:");
        eprintln!(" * `git remote set-head origin --auto` will help `git-trim` to automatically");
        eprintln!("   detect the base branch.");
        eprintln!("   If you see `origin/HEAD set to <base branch>` in the output of the previous");
        eprintln!("   command, then `git branch --set-upstream origin/<base branch> <base branch>`");
        eprintln!("   to set an upstream branch for <base branch> if exists.");
        eprintln!("You also can set bases manually with any of following commands:");
        eprintln!(" * `git config trim.bases develop,master` for a repository.");
        eprintln!(" * `git config --global trim.bases develop,master` to set globally.");
        eprintln!(" * `git trim --bases develop,master` to set temporarily.");
    }

    Ok(bases)
}

fn collect_branches(repo: &Repository) -> Result<(Vec<(String, bool)>, Vec<(String, String)>)> {
    let mut local_branches = Vec::new();
    let mut remote_branches = Vec::new();

    // Collect local branches
    let mut branches = repo.branches(Some(BranchType::Local))?;
    while let Some(Ok((branch, _))) = branches.next() {
        if let Some(name) = branch.name()? {
            let is_head = branch.is_head()?;
            local_branches.push((name.to_string(), is_head));
        }
    }

    // Collect remote branches
    let mut branches = repo.branches(Some(BranchType::Remote))?;
    while let Some(Ok((branch, _))) = branches.next() {
        if let Some(name) = branch.name()? {
            // name format is "origin/branch"
            if let Some((remote, branch_name)) = name.split_once('/') {
                remote_branches.push((remote.to_string(), branch_name.to_string()));
            }
        }
    }

    Ok((local_branches, remote_branches))
}

fn analyze_deletions(
    repo: &Repository,
    local_branches: &[(String, bool)],
    remote_branches: &[(String, String)],
    bases: &[String],
    _args: &Args,
) -> Result<BranchInfo> {
    let mut merged_local = Vec::new();

    // Get the base branch commit
    let head = repo.head()?;
    let head_oid = head.target().ok_or(anyhow!("Invalid HEAD"))?;

    // Check which local branches are merged
    for (branch_name, _is_head) in local_branches {
        if bases.contains(branch_name) {
            continue; // Don't delete base branches
        }

        // Check if this branch is merged into any base branch
        if let Ok(branch) = repo.find_branch(branch_name, BranchType::Local) {
            if let Some(oid) = branch.get().target() {
                for base in bases {
                    if let Ok(base_branch) = repo.find_branch(base, BranchType::Local) {
                        if let Some(base_oid) = base_branch.get().target() {
                            // Check if oid is an ancestor of base_oid
                            if is_ancestor(repo, oid, base_oid)? {
                                merged_local.push(branch_name.clone());
                                break;
                            }
                        }
                    }
                }
            }
        }
    }

    Ok(BranchInfo { merged_local })
}

fn is_ancestor(repo: &Repository, ancestor: git2::Oid, descendant: git2::Oid) -> Result<bool> {
    Ok(repo.graph_descendant_of(descendant, ancestor)?)
}
