use std::collections::{HashMap, HashSet};
use std::io::{self, BufRead};
use std::process::{Command, Stdio};
use std::env;
use std::path::Path;

#[derive(Debug)]
struct Args {
    bases: Option<String>,
    protected: Option<String>,
    no_update: bool,
    update_interval: u64,
    no_confirm: bool,
    no_detach: bool,
    delete: String,
    dry_run: bool,
    help: bool,
    version: bool,
}

fn main() {
    let args = parse_args();

    if args.help {
        print_help();
        return;
    }

    if args.version {
        println!("git-trim 0.4.4");
        return;
    }

    if let Err(e) = run(&args) {
        eprintln!("Error: {}", e);
        std::process::exit(1);
    }
}

fn parse_args() -> Args {
    let args: Vec<String> = env::args().collect();
    let mut result = Args {
        bases: None,
        protected: None,
        no_update: false,
        update_interval: 5,
        no_confirm: false,
        no_detach: false,
        delete: "merged:origin".to_string(),
        dry_run: false,
        help: false,
        version: false,
    };

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "-h" | "--help" => result.help = true,
            "-V" | "--version" => result.version = true,
            "-b" | "--bases" => {
                i += 1;
                if i < args.len() {
                    result.bases = Some(args[i].clone());
                }
            }
            "-p" | "--protected" => {
                i += 1;
                if i < args.len() {
                    result.protected = Some(args[i].clone());
                }
            }
            "--no-update" => result.no_update = true,
            "--update-interval" => {
                i += 1;
                if i < args.len() {
                    result.update_interval = args[i].parse().unwrap_or(5);
                }
            }
            "--no-confirm" => result.no_confirm = true,
            "--no-detach" => result.no_detach = true,
            "-d" | "--delete" => {
                i += 1;
                if i < args.len() {
                    result.delete = args[i].clone();
                }
            }
            "--dry-run" => result.dry_run = true,
            _ => {}
        }
        i += 1;
    }

    result
}

fn print_help() {
    println!("Automatically trims your tracking branches whose upstream branches are merged or stray.
`git-trim` is a missing companion to the `git fetch --prune` and a proper, safer, faster alternative to your `<bash oneliner HERE>`.

Usage: executable [OPTIONS]

Options:
  -b, --bases <BASES>
          Comma separated multiple names of branches. [default: branches that tracks `git symbolic-ref refs/remotes/*/HEAD`] [config: trim.bases]

          The default value is a branch that tracks `git symbolic-ref refs/remotes/*/HEAD`. They might not be reflected correctly when the HEAD branch of your remote repository is changed. You can see the changed HEAD branch name with `git remote show <remote>` and apply it to your local repository with `git remote set-head <remote> --auto`.

  -p, --protected <PROTECTED>
          Comma separated multiple glob patterns (e.g. `release-*`, `feature/*`) of branches that should never be deleted. [config: trim.protected]

      --no-update
          Do not update remotes [config: trim.update]

      --update-interval <UPDATE_INTERVAL>
          Prevents too frequent updates. Seconds between updates in seconds. 0 to disable. [default: 5] [config: trim.updateInterval]

      --no-confirm
          Do not ask confirm [config: trim.confirm]

      --no-detach
