fn get_remotes() -> Result<Vec<String>, String> {
    let output = Command::new("git")
        .args(&["remote"])
        .output()
        .map_err(|e| format!("Failed to get remotes: {}", e))?;

    if !output.status.success() {
        return Ok(Vec::new());
    }

    let remotes = String::from_utf8_lossy(&output.stdout)
        .lines()
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty())
        .collect();

    Ok(remotes)
}

fn get_base_branches(remotes: &[String], args: &Args) -> Result<Vec<String>, String> {
    if let Some(ref bases) = args.bases {
        return Ok(bases.split(',').map(|s| s.trim().to_string()).collect());
    }

    let mut bases = Vec::new();

    for remote in remotes {
        let output = Command::new("git")
            .args(&["symbolic-ref", &format!("refs/remotes/{}/HEAD", remote)])
            .output();

        if let Ok(output) = output {
            if output.status.success() {
                let ref_name = String::from_utf8_lossy(&output.stdout);
                let prefix = format!("refs/remotes/{}/", remote);
                if let Some(branch) = ref_name.strip_prefix(&prefix) {
                    bases.push(branch.trim().to_string());
                }
            }
        }
    }

    Ok(bases)
}

fn get_all_branches() -> Result<BranchesInfo, String> {
    let mut local_branches = Vec::new();
    let mut remote_branches = Vec::new();

    // Get all branches with tracking information
    let output = Command::new("git")
        .args(&["for-each-ref", "refs/heads", "--format=%(refname:short) %(upstream)"])
        .output()
        .map_err(|e| format!("Failed to list branches: {}", e))?;

    for line in String::from_utf8_lossy(&output.stdout).lines() {
        let parts: Vec<&str> = line.splitn(2, ' ').collect();
        if !parts.is_empty() {
            let branch_name = parts[0].to_string();
            let is_tracked = parts.len() > 1 && !parts[1].is_empty();
            local_branches.push((branch_name, is_tracked));
        }
    }

    // Get all remote branches
    let output = Command::new("git")
        .args(&["branch", "-r", "--format=%(refname:short)"])
        .output()
        .map_err(|e| format!("Failed to list remote branches: {}", e))?;

    for line in String::from_utf8_lossy(&output.stdout).lines() {
        let branch = line.trim();
        if !branch.is_empty() && !branch.ends_with("/HEAD") {
            if let Some((remote, branch_name)) = branch.split_once('/') {
                remote_branches.push((remote.to_string(), branch_name.to_string()));
            }
        }
    }

    Ok(BranchesInfo {
        local_branches,
        remote_branches,
    })
}

fn analyze_deletions(
    tracked_local: &[String],
    _remote_branches: &[(String, String)],
    bases: &[String],
    _args: &Args,
) -> Result<DeletionResult, String> {
    let mut merged_local = Vec::new();

    for branch in tracked_local {
        if bases.contains(branch) {
            continue;
        }

        // Check if this branch is merged into any base branch
        let is_merged = bases.iter().any(|base| {
            let output = Command::new("git")
                .args(&["merge-base", "--is-ancestor", branch, base])
                .output();

            output.map(|o| o.status.success()).unwrap_or(false)
        });

        if is_merged {
            merged_local.push(branch.clone());
        }
    }

    Ok(DeletionResult { merged_local })
}
